fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut left = 0;
    let mut right = v.len() - 1;
    
    while left <= right {
        let mid = left + (right - left) / 2;
        
        if v[mid] == k {
            return mid;
        } else if v[mid] < k {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    
    // This line should never be reached since k is guaranteed to be in v
    // But we need to return something to satisfy the compiler
    unreachable!("Target value {} not found in array, but it should be present", k);
}